class Matrix3D:
    def __init__(self, n: int):
        self.n = n
        self.cnt = [0] * n
    def setCell(self, x: int, y: int, z: int) -> None:
        self.cnt[x] += 1
    def unsetCell(self, x: int, y: int, z: int) -> None:
        self.cnt[x] -= 1
    def largestMatrix(self) -> int:
        b = self.n - 1
        for x in range(self.n - 1, -1, -1):
            if self.cnt[x] > self.cnt[b]: b = x
        return b

