class Matrix3D {
    vector<int> cnt; int n;
public:
    Matrix3D(int n) : cnt(n, 0), n(n) {}
    void setCell(int x, int y, int z) { cnt[x]++; }
    void unsetCell(int x, int y, int z) { cnt[x]--; }
    int largestMatrix() {
        int b = n - 1;
        for (int x = n - 1; x >= 0; x--) if (cnt[x] > cnt[b]) b = x;
        return b;
    }
};

