import heapq
class Matrix3D:
    def __init__(self, n: int):
        self.n = n
        self.cnt = [0] * n
        self.h = []
    def setCell(self, x: int, y: int, z: int) -> None:
        self.cnt[x] += 1
        heapq.heappush(self.h, (-self.cnt[x], x))
    def unsetCell(self, x: int, y: int, z: int) -> None:
        self.cnt[x] -= 1
    def largestMatrix(self) -> int:
        while self.h and -self.h[0][0] != self.cnt[self.h[0][1]]:
            heapq.heappop(self.h)
        return self.h[0][1] if self.h else self.n - 1

