class Matrix3D {
    vector<int> cnt; int n;
    priority_queue<pair<int,int>> pq;
public:
    Matrix3D(int n) : cnt(n, 0), n(n) {}
    void setCell(int x, int y, int z) { cnt[x]++; pq.push({-cnt[x], x}); }
    void unsetCell(int x, int y, int z) { cnt[x]--; }
    int largestMatrix() {
        while (!pq.empty() && -pq.top().first != cnt[pq.top().second]) pq.pop();
        return pq.empty() ? n - 1 : pq.top().second;
    }
};

