class Matrix3D {
    private int[] cnt; private int n;
    private PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
    public Matrix3D(int n) { this.n = n; cnt = new int[n]; }
    public void setCell(int x, int y, int z) { cnt[x]++; pq.add(new int[]{-cnt[x], x}); }
    public void unsetCell(int x, int y, int z) { cnt[x]--; }
    public int largestMatrix() {
        while (!pq.isEmpty() && -pq.peek()[0] != cnt[pq.peek()[1]]) pq.poll();
        return pq.isEmpty() ? n - 1 : pq.peek()[1];
    }
}

